1: // Cliente — um cliente que chega à porta da discoteca.
2: //
3: // É um Container do Phaser: um objeto que AGRUPA outros (aqui, o corpo
4: // placeholder + a legenda com os atributos). Vantagem: posicionamos e
5: // destruímos o cliente todo de uma vez, e as posições dos filhos passam a
6: // ser relativas ao container (0,0 = centro do cliente).
7: class Cliente extends Phaser.GameObjects.Container {
8:   constructor(scene, x, y) {
9:     // super() do Container precisa da cena e da posição.
10:     super(scene, x, y);
11: 
12:     // Atributos aleatórios — é com base nisto que o jogador vai decidir.
13:     // Fica guardado em this.atributos para a lógica de regras (passo 3) ler.
14:     this.atributos = Cliente.gerarAtributos();
15: 
16:     // Sprite do cliente. Posicionado para que a base (pés) fique alinhada.
17:     // Container Y=710, sprite local Y=220 → pés no mundo a Y=930 (chão).
18:     // Dimensões reais: andar 356x593/frame, parado 489x1163.
19:     this.sprite = scene.add.sprite(0, 220, 'cliente_andar');
20:     this.sprite.setOrigin(0.5, 1);
21: 
22:     // Legenda com os atributos, por baixo do corpo.
23:     const a = this.atributos;
24:     this.legenda = scene.add.text(
25:       0, 230,
26:       `Idade: ${a.idade}\nCalçado: ${a.calcado}\nChapéu: ${a.chapeu ? 'sim' : 'não'}`,
27:       { fontSize: '26px', color: '#ffffff', align: 'center',
28:         backgroundColor: '#12121acc', padding: { x: 12, y: 6 } }
29:     ).setOrigin(0.5, 0);
30: 
31:     // add() mete os filhos DENTRO do container.
32:     this.add([this.sprite, this.legenda]);
33: 
34:     // Inicia com o estado de andar
35:     this.andar();
36: 
37:     // add.existing() regista o container na cena. Sem isto, nada aparece.
38:     scene.add.existing(this);
39:   }
40: 
41:   // Ativa a animação de andar
42:   andar() {
43:     this.sprite.setTexture('cliente_andar');
44:     this.sprite.setOrigin(0.5, 1);
45:     this.sprite.setScale(0.6); // 356x593 → ~214x356 em ecrã
46:     this.sprite.play('andar');
47:     if (this.legenda) this.legenda.setVisible(false);
48:   }
49: 
50:   // Pára a animação de andar e mostra a sprite de frente
51:   parar() {
52:     this.sprite.stop();
53:     this.sprite.setTexture('cliente_parado');
54:     this.sprite.setOrigin(0.5, 1);
55:     this.sprite.setScale(0.3); // 489x1163 → ~147x349 em ecrã
56:     if (this.legenda) this.legenda.setVisible(true);
57:   }
58: 
59:   // Método static: pertence à classe, não a uma instância. Útil como "fábrica"
60:   // de atributos — podemos chamá-lo sem ter um Cliente criado.
61:   static gerarAtributos() {
62:     return {
63:       // Between() é inclusivo nos dois extremos.
64:       idade: Phaser.Math.Between(14, 30),
65:       // GetRandom() escolhe um item aleatório do array.
66:       calcado: Phaser.Utils.Array.GetRandom(['crocs', 'ténis', 'botas']),
67:       // 0 ou 1 → false/true.
68:       chapeu: Phaser.Math.Between(0, 1) === 1,
69:     };
70:   }
71: }
